<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Pointly POS | Record Sale</title><?= view('partials/styles') ?></head><body><div class="app-shell"><?= view('partials/nav', ['active' => 'sales']) ?><main class="content"><header class="topbar"><div><p class="eyebrow">Transactions</p><h1>Record sale</h1><p class="subtitle">Select a product and quantity to update inventory.</p></div><div class="profile"><div class="avatar">AD</div> Admin account</div></header><section class="panel"><?php if (session()->getFlashdata('error')): ?><div class="form-error"><?= esc(session()->getFlashdata('error')) ?></div><?php endif; ?><form action="<?= base_url('sales/create') ?>" method="post"><div class="form-grid"><div class="field full"><label for="product_id">Product</label><select class="input" id="product_id" name="product_id" required><option value="">Select a product</option><?php foreach ($products as $product): ?><option value="<?= $product['id'] ?>"><?= esc($product['name']) ?> — ₱<?= number_format((float) $product['price'], 2) ?> (<?= $product['stock_quantity'] ?> in stock)</option><?php endforeach; ?></select></div><div class="field"><label for="customer_id">Customer (optional)</label><select class="input" id="customer_id" name="customer_id"><option value="">Walk-in customer</option><?php foreach ($customers as $customer): ?><option value="<?= $customer['id'] ?>"><?= esc($customer['full_name']) ?></option><?php endforeach; ?></select></div><div class="field"><label for="quantity">Quantity</label><input class="input" type="number" id="quantity" name="quantity" min="1" required></div></div><div class="form-actions"><button class="button" type="submit">Record sale</button><a class="button secondary" href="<?= base_url('sales') ?>">Cancel</a></div></form></section></main></div></body></html>
